package org.apache.commons.jxpath.ri;

import org.apache.commons.jxpath.ri.model.NodePointerFactory;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class RemoveNodePointerFactoryTests {

    @Mock
    private NodePointerFactory factory1;

    @Mock
    private NodePointerFactory factory2;

    @Mock
    private NodePointerFactory factory3;

    @Before
    public void setUp() {
        // Reset the static nodeFactories list before each test
        try {
            java.lang.reflect.Field field = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactories");
            field.setAccessible(true);
            List<NodePointerFactory> emptyList = new ArrayList<>();
            field.set(null, emptyList);

            java.lang.reflect.Field arrayField = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactoryArray");
            arrayField.setAccessible(true);
            arrayField.set(null, null);
        } catch (Exception e) {
            fail("Failed to reset static fields: " + e.getMessage());
        }
    }

    @Test
    public void testRemoveNodePointerFactory_WhenFactoryExists() {
        // Setup
        addFactoryToStaticList(factory1);
        addFactoryToStaticList(factory2);

        // Execute
        boolean result = JXPathContextReferenceImpl.removeNodePointerFactory(factory1);

        // Verify
        assertTrue("Should return true when factory is removed", result);
        assertFalse("Factory should no longer be in the list", isFactoryInStaticList(factory1));
        assertTrue("Other factory should still be in the list", isFactoryInStaticList(factory2));
    }

    @Test
    public void testRemoveNodePointerFactory_WhenFactoryDoesNotExist() {
        // Setup
        addFactoryToStaticList(factory1);
        addFactoryToStaticList(factory2);

        // Execute
        boolean result = JXPathContextReferenceImpl.removeNodePointerFactory(factory3);

        // Verify
        assertFalse("Should return false when factory is not in the list", result);
        assertTrue("Factory1 should still be in the list", isFactoryInStaticList(factory1));
        assertTrue("Factory2 should still be in the list", isFactoryInStaticList(factory2));
    }

    @Test
    public void testRemoveNodePointerFactory_FromEmptyList() {
        // Execute
        boolean result = JXPathContextReferenceImpl.removeNodePointerFactory(factory1);

        // Verify
        assertFalse("Should return false when list is empty", result);
    }

    @Test
    public void testRemoveNodePointerFactory_RemovesAllOccurrences() {
        // Setup - Add factory1 twice (though this shouldn't normally happen)
        addFactoryToStaticList(factory1);
        addFactoryToStaticList(factory1);
        addFactoryToStaticList(factory2);

        // Execute
        boolean result = JXPathContextReferenceImpl.removeNodePointerFactory(factory1);

        // Verify
        assertTrue("Should return true when at least one factory is removed", result);
        assertFalse("All instances of factory1 should be removed", isFactoryInStaticList(factory1));
        assertTrue("Factory2 should still be in the list", isFactoryInStaticList(factory2));
    }

    @Test
    public void testRemoveNodePointerFactory_ThreadSafety() throws Exception {
        // Setup
        addFactoryToStaticList(factory1);
        addFactoryToStaticList(factory2);

        // Create multiple threads that will try to remove factories concurrently
        Thread thread1 = new Thread(() -> JXPathContextReferenceImpl.removeNodePointerFactory(factory1));
        Thread thread2 = new Thread(() -> JXPathContextReferenceImpl.removeNodePointerFactory(factory2));

        // Execute threads concurrently
        thread1.start();
        thread2.start();

        // Wait for threads to complete
        thread1.join();
        thread2.join();

        // Verify - At least one factory should have been successfully removed
        // and no exceptions should have been thrown due to concurrent modification
        int remainingFactories = getStaticListSize();
        assertTrue("Should have 0 or 1 factories remaining after concurrent removal", 
                   remainingFactories >= 0 && remainingFactories <= 1);
    }

    @Test
    public void testRemoveNodePointerFactory_ResetsNodeFactoryArray() throws Exception {
        // Setup
        addFactoryToStaticList(factory1);

        // First, get the array to be populated
        java.lang.reflect.Method method = JXPathContextReferenceImpl.class.getDeclaredMethod("getNodeFactoryArray");
        method.setAccessible(true);
        Object[] initialArray = (Object[]) method.invoke(null);
        assertNotNull("Array should be initialized", initialArray);

        // Execute
        JXPathContextReferenceImpl.removeNodePointerFactory(factory1);

        // Verify array is reset to null
        java.lang.reflect.Field arrayField = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactoryArray");
        arrayField.setAccessible(true);
        Object[] arrayAfterRemoval = (Object[]) arrayField.get(null);

        assertNull("nodeFactoryArray should be null after removal", arrayAfterRemoval);
    }

    @Test
    public void testRemoveNodePointerFactory_NullFactory() {
        // Setup
        addFactoryToStaticList(factory1);

        // Execute
        boolean result = JXPathContextReferenceImpl.removeNodePointerFactory(null);

        // Verify
        assertFalse("Should return false for null factory", result);
        assertTrue("Original factory should still be in the list", isFactoryInStaticList(factory1));
    }

    // Helper methods to manipulate the static list
    private void addFactoryToStaticList(NodePointerFactory factory) {
        try {
            java.lang.reflect.Field field = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactories");
            field.setAccessible(true);
            @SuppressWarnings("unchecked")
            List<NodePointerFactory> list = (List<NodePointerFactory>) field.get(null);
            list.add(factory);
        } catch (Exception e) {
            fail("Failed to add factory to static list: " + e.getMessage());
        }
    }

    private boolean isFactoryInStaticList(NodePointerFactory factory) {
        try {
            java.lang.reflect.Field field = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactories");
            field.setAccessible(true);
            @SuppressWarnings("unchecked")
            List<NodePointerFactory> list = (List<NodePointerFactory>) field.get(null);
            return list.contains(factory);
        } catch (Exception e) {
            fail("Failed to check factory in static list: " + e.getMessage());
        }
        return false;
    }

    private int getStaticListSize() {
        try {
            java.lang.reflect.Field field = JXPathContextReferenceImpl.class.getDeclaredField("nodeFactories");
            field.setAccessible(true);
            @SuppressWarnings("unchecked")
            List<NodePointerFactory> list = (List<NodePointerFactory>) field.get(null);
            return list.size();
        } catch (Exception e) {
            fail("Failed to get static list size: " + e.getMessage());
        }
        return 0;
    }
}

